module iosbuild

import cachecli
import os

pub fn symbol_outputs(text string) !(string, string) {
	names := text.split_into_lines().filter(it != '' && !it.starts_with('#'))
	mut seen := map[string]bool{}
	for name in names {
		if name in seen || !name.starts_with('_') { return error('invalid/duplicate C++ symbol') }
		seen[name] = true
	}
	mut lines := ['/* SPDX-License-Identifier: GPL-2.0-or-later */',
		'/* Generated by build-support/ios/generate-cxx-symbols. */', '#ifndef VINIX_IOS_CXX_SYMBOLS_H',
		'#define VINIX_IOS_CXX_SYMBOLS_H', '#include <stdint.h>', '#include <string.h>',
		'#ifdef __APPLE__', '#define IOS_CXX_ASM(name) "_" name', '#else',
		'#define IOS_CXX_ASM(name) name', '#endif']
	for index, name in names {
		lines << 'extern const unsigned char ios_cxx_' + index.str() + '[] __asm__(IOS_CXX_ASM("' + name[1..] + '"));'
	}
	lines << 'static uintptr_t ios_cxx_symbol(const char *name) {'
	for index, name in names {
		lines << '    if (!strcmp(name, "' + name + '")) return (uintptr_t)ios_cxx_' + index.str() + ';'
	}
	lines << ['    return 0;', '}', '#undef IOS_CXX_ASM', '#endif', '']
	if '__Unwind_Resume' !in names { return error('C++ symbol list is missing __Unwind_Resume') }
	stub := "--- !tapi-tbd\ntbd-version: 4\ntargets: [ arm64-ios ]\ninstall-name: '/usr/lib/libc++.1.dylib'\nexports:\n  - targets: [ arm64-ios ]\n    symbols: [\n      " + names.filter(it != '__Unwind_Resume').join(',\n      ') + '\n    ]\n...\n'
	return lines.join('\n'), stub
}

pub fn symbols_cli(tools Tools, argv []string) !int {
	args := cachecli.arguments(argv, ['--output'], [], [], 0, 0, 'Generate C++ symbol-address declarations and an iOS linker stub.\nUsage: generate-cxx-symbols [--output REPOSITORY]') or { return error_with_code(err.msg(), 2) }
	output := resolved(args.value('--output', tools.root))!
	header, stub := symbol_outputs(os.read_file(tools.root + '/compat/ios/runner/abi/cxx-symbols.txt')!)!
	mkdir(output + '/compat/ios/runner/abi')!
	mkdir(output + '/tests/ios')!
	publish(output + '/compat/ios/runner/abi/cxx-symbols.h', header)!
	publish(output + '/tests/ios/libcxx.tbd', stub)!
	return 0
}
